import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string; status: JobStatus; input: string; steps: number; failAttempts: number;
  attempts: number; progress: { completed: number; total: number };
  result: { output: string } | null; error: string | null; createdAt: string; updatedAt: string;
}
type Row = { id: string; status: JobStatus; input: string; steps: number; fail_attempts: number;
  attempts: number; completed: number; output: string | null; error: string | null;
  created_at: string; updated_at: string };

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0, output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0,
      idempotency_key TEXT UNIQUE, payload TEXT
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), seen_at INTEGER NOT NULL);
  `);
  return db;
}

export function toJob(row: Row): Job {
  return { id: row.id, status: row.status, input: row.input, steps: row.steps, failAttempts: row.fail_attempts,
    attempts: row.attempts, progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null, createdAt: row.created_at, updatedAt: row.updated_at };
}

export const selectJob = (db: DatabaseSync, id: string): Job | undefined => {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as Row | undefined;
  return row ? toJob(row) : undefined;
};

