import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, selectJob, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = ''; for await (const chunk of req) { body += chunk.toString(); if (body.length > 100_000) throw new Error('body too large'); }
  return body;
}
const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const idMatch = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || !!idMatch;
  if (!known) return error(res, 404, 'not_found', 'Not found.');
  if ((pathname === '/' || pathname === '/health') && req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if ((pathname === '/api/jobs' && !['GET','POST'].includes(req.method ?? '')) || (idMatch && req.method !== 'GET'))
    return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    const beat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as {seen_at:number}|undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.seen_at < 3000 ? 'up' : 'down' });
  }
  if (idMatch) {
    const job = selectJob(db, decodeURIComponent(idMatch[1]!));
    return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  if (req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all();
    return send(res, 200, { jobs: rows.map(row => toJob(row as Parameters<typeof toJob>[0])) });
  }

  const fields: {field:string;message:string}[] = [];
  const contentType = req.headers['content-type'] ?? '';
  let raw = '';
  try {
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({field:'body',message:'Content-Type must be application/json.'});
    raw = await readBody(req);
  } catch { fields.push({field:'body',message:'Request body is too large or unreadable.'}); }
  let value: unknown; let parsed = false;
  if (!fields.length) { try { value = JSON.parse(raw); parsed = true; } catch { fields.push({field:'body',message:'Body must be valid JSON.'}); } }
  if (parsed && (!value || typeof value !== 'object' || Array.isArray(value))) { fields.push({field:'body',message:'Body must be a JSON object.'}); parsed = false; }
  const obj = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  let steps: unknown = 5; let failAttempts: unknown = 0;
  if (parsed) {
  for (const field of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(field)) fields.push({field,message:'Unknown field.'});
  if (!Object.hasOwn(obj,'input')) fields.push({field:'input',message:'Required.'});
  else if (typeof obj.input !== 'string') fields.push({field:'input',message:'Must be a string.'});
  else if (obj.input.length < 1 || obj.input.length > 1000 || !obj.input.trim()) fields.push({field:'input',message:'Must be 1–1000 characters and not only whitespace.'});
  steps = Object.hasOwn(obj,'steps') ? obj.steps : 5;
  failAttempts = Object.hasOwn(obj,'failAttempts') ? obj.failAttempts : 0;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({field:'steps',message:'Must be an integer from 1 to 20.'});
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({field:'failAttempts',message:'Must be an integer from 0 to 5.'});
  }
  const key = req.headers['idempotency-key'];
  if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({field:'Idempotency-Key',message:'Must contain 1–128 letters, numbers, underscores, or hyphens.'});
  if (fields.length) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);

  const input = obj.input as string; const normalizedSteps = steps as number; const normalizedFails = failAttempts as number;
  const idempotencyKey = typeof key === 'string' ? key : undefined;
  const payload = JSON.stringify({input, steps:normalizedSteps, failAttempts:normalizedFails});
  try {
    db.exec('BEGIN IMMEDIATE');
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(idempotencyKey) as (Parameters<typeof toJob>[0] & {payload:string})|undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload !== payload) return error(res,409,'idempotency_conflict','Idempotency key was already used with a different payload.');
        return send(res,200,toJob(existing));
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,completed,created_at,updated_at,idempotency_key,payload)
      VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`).run(id,input,normalizedSteps,normalizedFails,now,now,idempotencyKey ?? null,idempotencyKey === undefined ? null : payload);
    db.exec('COMMIT');
    return send(res,201,selectJob(db,id));
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch {}
    console.error('submission error', e); return error(res,500,'internal_error','Unable to create job.');
  }
});
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

