9	    body{max-width:850px;margin:40px auto;padding:0 20px}h1{font-size:2rem;margin-bottom:6px}p{color:#5a6574}
10	    form,.job{background:white;border:1px solid #dce2e9;border-radius:12px;padding:20px;margin:18px 0;box-shadow:0 2px 8px #192a3b0a}
11	    form{display:grid;grid-template-columns:1fr 130px 150px auto;gap:12px;align-items:end}label{display:grid;gap:6px;font-size:.9rem;font-weight:600}
12	    input{font:inherit;padding:9px;border:1px solid #bac5d1;border-radius:7px;min-width:0}button{font:inherit;background:#2358c5;color:white;border:0;border-radius:7px;padding:10px 15px;cursor:pointer}
13	    [role=alert]{color:#a32222;min-height:1.4em;margin:8px 0}.job-list{padding:0;list-style:none}.job{display:grid;grid-template-columns:1fr auto;gap:8px 16px}.job strong{overflow-wrap:anywhere}.meta{color:#5a6574;font-size:.9rem}.output{grid-column:1/-1;overflow-wrap:anywhere;color:#176348}
14	    @media(max-width:650px){form{grid-template-columns:1fr 1fr}form label:first-child{grid-column:1/-1}form button{grid-column:1/-1}}
15	  </style>
16	</head>
17	<body>
18	  <h1>Job tracker</h1>
19	  <p>Submit work and follow its progress.</p>
20	  <form data-testid="job-form" id="job-form">
21	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000" autocomplete="off"></label>
22	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5"></label>
23	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0"></label>
24	    <button data-testid="job-submit" type="submit">Submit job</button>
25	  </form>
26	  <div data-testid="form-error" role="alert" aria-live="polite"></div>
27	  <h2>Jobs</h2>
28	  <ul data-testid="job-list" class="job-list"></ul>
29	  <script>
30	    const form=document.querySelector('[data-testid="job-form"]');
31	    const alertBox=document.querySelector('[data-testid="form-error"]');
32	    const list=document.querySelector('[data-testid="job-list"]');
33	    function node(tag,text,attrs={}){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el}
34	    async function refresh(){try{const response=await fetch('/api/jobs');if(!response.ok)return;const {jobs}=await response.json();list.replaceChildren(...jobs.map(job=>{
35	      const li=node('li',undefined,{class:'job','data-testid':'job-item','data-job-id':job.id});
36	      const title=node('strong',job.input);const status=node('span',job.status,{'data-testid':'job-status'});
37	      const info=node('span',`Progress `);info.className='meta';info.append(node('span',`${job.progress.completed}/${job.progress.total}`,{'data-testid':'job-progress'}));
38	      const attempts=node('span',` · Attempts ${job.attempts}`);info.append(attempts);
39	      const result=node('div',job.result?.output||job.error||'',{'data-testid':'job-result'});result.className='output';
40	      li.append(title,status,info,result);return li;
41	    }));}catch{}}
42	    form.addEventListener('submit',async event=>{event.preventDefault();alertBox.textContent='';const data=new FormData(form);const payload={input:data.get('input'),steps:Number(data.get('steps')),failAttempts:Number(data.get('failAttempts'))};
43	      try{const response=await fetch('/api/jobs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok){const details=body.error?.fields?.map(field=>`${field.field}: ${field.message}`).join(' · ');alertBox.textContent=details||body.error?.message||'Unable to submit job.';}else{form.elements.input.value='';await refresh();}}
44	      catch{alertBox.textContent='Unable to reach the server.';}
45	    });
46	    refresh();setInterval(refresh,500);
47	  </script>
48	</body>
